import{_ as a,o as e,c as r,ae as l}from"./chunks/framework.CJnqVqMy.js";const p=JSON.parse('{"title":"面临的挑战","description":"","frontmatter":{},"headers":[],"relativePath":"challenges.md","filePath":"challenges.md"}'),o={name:"challenges.md"};function d(n,t,i,h,s,u){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="面临的挑战" tabindex="-1">面临的挑战 <a class="header-anchor" href="#面临的挑战" aria-label="Permalink to &quot;面临的挑战&quot;">​</a></h1><p>评测基准在推动 AI 进步的同时，自身也暴露出一系列系统性问题。理解这些挑战，才能正确解读基准分数背后的真实含义。</p><h2 id="数据污染" tabindex="-1">数据污染 <a class="header-anchor" href="#数据污染" aria-label="Permalink to &quot;数据污染&quot;">​</a></h2><p>最普遍也最致命的问题。基准数据集被泄漏或混入模型的训练语料，导致&quot;高分 ≠ 真能力&quot;。</p><p>MMLU、GSM8K 等静态基准的题目在互联网上广泛传播，无法排除模型&quot;背过答案&quot;的可能。部分厂商甚至被质疑在训练集中刻意混入评测数据以刷榜。</p><table tabindex="0"><thead><tr><th>应对方案</th><th>代表基准</th><th>策略</th></tr></thead><tbody><tr><td>动态题库</td><td>LiveBench</td><td>每月更换题目，从源头抵抗污染</td></tr><tr><td>实时人类盲评</td><td>Chatbot Arena</td><td>题目即时生成，完全绕开数据泄漏</td></tr><tr><td>极限难度</td><td>Humanity&#39;s Last Exam</td><td>题目来自全球专家众包，发布前从未公开</td></tr></tbody></table><h2 id="goodhart-定律" tabindex="-1">Goodhart 定律 <a class="header-anchor" href="#goodhart-定律" aria-label="Permalink to &quot;Goodhart 定律&quot;">​</a></h2><blockquote><p>当一个指标变成目标，它就不再是好指标。</p></blockquote><p>基准分数成为营销指标后，厂商开始针对特定基准过拟合优化，而非提升通用能力：</p><ul><li>模型在 GSM8K 上接近满分，但面对稍微变形的数学题就失败</li><li>HumanEval 分数很高的模型，处理真实代码仓库（SWE-bench）时表现断崖下降</li><li>MMLU 57 个学科分数很高，但实际对话中常识错误频出</li></ul><p>这正是评测维度不断分化的根本原因——单一基准上的高分越来越不可信，社区需要更多角度的交叉验证。</p><h2 id="基准饱和" tabindex="-1">基准饱和 <a class="header-anchor" href="#基准饱和" aria-label="Permalink to &quot;基准饱和&quot;">​</a></h2><p>模型快速逼近基准天花板后，分数失去区分度：</p><table tabindex="0"><thead><tr><th>基准</th><th>顶级模型表现</th><th>后果</th></tr></thead><tbody><tr><td>GLUE / SuperGLUE</td><td>超越人类基线</td><td>完全失去区分度，已退役</td></tr><tr><td>GSM8K</td><td>95%+</td><td>主流模型之间无法区分</td></tr><tr><td>HellaSwag</td><td>95%+</td><td>沦为&quot;及格线检查&quot;</td></tr><tr><td>MMLU</td><td>90%+</td><td>头部模型差距仅 1–2 个百分点</td></tr></tbody></table><p>饱和后只有两条路：造更难的基准（ARC-AGI → ARC-AGI-2），或换评测范式（静态题目 → 动态对抗）。两条路社区都在走。</p><h2 id="标注质量" tabindex="-1">标注质量 <a class="header-anchor" href="#标注质量" aria-label="Permalink to &quot;标注质量&quot;">​</a></h2><p>基准本身的标注可能有错，导致模型被错误惩罚或奖励。</p><ul><li><strong>SWE-bench</strong> 原版中存在标注噪声，部分任务的&quot;正确答案&quot;本身有争议。这直接促使 OpenAI 联合 Princeton 推出了经人工审核的 SWE-bench Verified（500 题子集）</li><li><strong>TruthfulQA</strong> 的部分&quot;真实答案&quot;随时间推移可能不再准确</li><li><strong>BIG-bench</strong> 204 个任务质量参差不齐，社区后来提炼出 BIG-bench Hard 子集聚焦高质量题目</li></ul><p>标注质量问题的本质是：<strong>构建高质量基准本身就是一项极其昂贵的工程。</strong></p><h2 id="开放式生成的评判困境" tabindex="-1">开放式生成的评判困境 <a class="header-anchor" href="#开放式生成的评判困境" aria-label="Permalink to &quot;开放式生成的评判困境&quot;">​</a></h2><p>传统基准能用准确率自动判分，但 LLM 的核心能力是生成开放式文本——这没有标准答案。</p><p>LLM-as-Judge 方案（用 GPT-4 等强模型作为裁判）引入了新的偏见：</p><ul><li><strong>冗长偏好</strong> —— 偏好更长、更详细的回答，即使简短回答更准确</li><li><strong>自我增强</strong> —— 对自身输出的评分偏高</li><li><strong>位置偏见</strong> —— 对先出现的答案评分偏高</li></ul><p>AlpacaEval 1.0 就因高度偏好冗长回答而受到批评，2.0 通过长度控制回归（Length-Controlled）修正了这一问题。Chatbot Arena 通过大规模人类盲评部分缓解了评判偏见，但成本极高。</p><h2 id="生态公平性" tabindex="-1">生态公平性 <a class="header-anchor" href="#生态公平性" aria-label="Permalink to &quot;生态公平性&quot;">​</a></h2><p>评测基准的设计往往隐含对特定模型或文化的偏向。</p><ul><li><strong>语言偏见</strong> —— 绝大多数基准以英文为主，中文模型需要 C-Eval、CMMLU 等专项基准才能被公平评估。其他语言的评测空白更为严重</li><li><strong>闭源优势</strong> —— Chatbot Arena 对闭源商业模型更友好（可随时更新部署），开源模型的&quot;快照&quot;一旦上线就固定了</li><li><strong>评测成本</strong> —— SWE-bench、WebArena 等端到端基准需要大量算力运行，小团队和学术机构难以负担完整评测</li></ul><h2 id="静态基准与动态能力的错位" tabindex="-1">静态基准与动态能力的错位 <a class="header-anchor" href="#静态基准与动态能力的错位" aria-label="Permalink to &quot;静态基准与动态能力的错位&quot;">​</a></h2><p>基准拍的是&quot;快照&quot;，但 AI 的真实应用是连续交互。</p><ul><li>模型在 MT-Bench 的 2 轮对话中表现良好，但在 10+ 轮后严重退化——上下文遗忘、自我矛盾</li><li>Agent 基准（WebArena、GAIA）只测单次任务，无法反映 Agent 在长时间持续运行中的稳定性和错误恢复能力</li><li>安全评测（TruthfulQA）测的是静态问答，无法覆盖多轮对话中的渐进式诱导攻击</li></ul><p>这个问题尚无成熟的解决方案，是当前评测领域最大的盲区之一。</p><h2 id="评测与真实应用的鸿沟" tabindex="-1">评测与真实应用的鸿沟 <a class="header-anchor" href="#评测与真实应用的鸿沟" aria-label="Permalink to &quot;评测与真实应用的鸿沟&quot;">​</a></h2><p>高基准分数不等于好的用户体验，这是当前最大的信任危机。</p><ul><li>模型在所有基准上都是 SOTA，但用户实际使用中频繁遇到幻觉、拒绝回答、格式错乱</li><li>SWE-bench 解决率 50% 听起来不错，但意味着一半任务会失败——在生产环境中这是不可接受的</li><li>基准不测试延迟、成本、一致性等生产级关注点</li></ul><p>SWE-Lancer 和 Tau-bench 代表了弥合这一鸿沟的尝试：前者用真实市场定价衡量产出价值，后者在真实商业场景中评估可靠性。但评测与应用之间的距离仍然很大。</p>',35)])])}const b=a(o,[["render",d]]);export{p as __pageData,b as default};
